(** * BB(12) candidate T12a = 1RB0RA_1LC1LF_1RD0LB_1RA1LE_1LI0LC_0RG1LD_1RH1LG_1LC0RG_0LJ0LI_1RK0LC_0RL---_0RF--- halts *)

(** Generated by bb8_list/investigations/bb12_t12a_coq (gen_final12.py).  T12a is n1 (Coq-proved 10-state
    f_(omega+1) machine, 1RB0RA_1LC1LF_1RD0LB_1RA1LE_1LI0LC_0RG1LD_1RH1LG_1LC0RG_0LJ0LI_---0LC) with J0 := 1RK and two
    new states K = 0RL---, L = 0RF--- (K1, L1 are the halts).  It runs n1's round 1, restarts in place from the
    accumulator (J0 -> 1RK -> 0RL -> 0RF detours), runs a second full round, and halts on L1 after round 2.
    Machine-level lemmas are generated by mexp.py (specs: gen_base.py, evs.py, evs12.py, evs_end.py); the abstract
    part is abstract.v.in, abstract2_12.v.in, arith.v.in, arith12.v.in, round1_12.v.in, wrappers.v.in,
    restart.v.in, wrappers_end.v.in, end.v.in, end_main.v.in.

    B-form (head in H on the blank right of the word; D(m) = (10)^m 1; tokens nearest-first):
      Bf L ts A = L D(t_1) .. D(t_n) D(0) D(A) H> 0^inf      (ts = [t_n; ..; t_1]).
    Champion rules (as for n1): R1, R2, clearing CLR with U 0 A = 2A+8, U (j+1) A = (U j)^(A/3+1) (4);
    Per L k m n a = [L, 2^k, 5, 1^m, 0, 0, 2, 1^n | a], PERIOD: m -> m - 14 with n' >= F (F n), F n = 2 ^(n arrows) 4.
    Run from the blank tape:
      round 1 (n1's run) up to Bf (FarE k) (1^w ++ [0]) f, w >= F^(2 JJ + 1)(34), JJ = (3T-13)/7, T = 2 ^(37 arrows) 3;
      restart (R1END, E0..E12 with 12 clearings; T12a reads J0 there): Per (lfr [p;3] (FarR k)) 1 (14 J + 3) n a,
        F w <= 7 J + 9;
      round 2 (J periods): Per .. (4 J + 1) 3 n' a', n' >= F^(2 J)(w);
      round-2 end: E20, the depth list becomes n'+1 blocks D3 D2 D0 (one per event), a clearing from 4 at depth 3
        (A24 = iter 3 (U 3) 4 = 40 + 9 y), the blocks are eaten six per loop round (6 cases by the count mod 6),
        then 2-3 continuation events, one or two shallow clearings, and the halt (state L reads 1). *)


From BB8 Require Import Individual122.
From Coq Require Import Lia PeanoNat List.
Import ListNotations.
Set Default Goal Selector "!".

(* machine: 1RB0RA_1LC1LF_1RD0LB_1RA1LE_1LI0LC_0RG1LD_1RH1LG_1LC0RG_0LJ0LI_1RK0LC_0RL---_0RF--- *)
Definition tm : TM := fun '(q, s) =>
  match q, s with
  | A, 0 => Some (1, TM.R, B)  | A, 1 => Some (0, TM.R, A)
  | B, 0 => Some (1, TM.L, C)  | B, 1 => Some (1, TM.L, F)
  | C, 0 => Some (1, TM.R, D)  | C, 1 => Some (0, TM.L, B)
  | D, 0 => Some (1, TM.R, A)  | D, 1 => Some (1, TM.L, E)
  | E, 0 => Some (1, TM.L, I)  | E, 1 => Some (0, TM.L, C)
  | F, 0 => Some (0, TM.R, G)  | F, 1 => Some (1, TM.L, D)
  | G, 0 => Some (1, TM.R, H)  | G, 1 => Some (1, TM.L, G)
  | H, 0 => Some (1, TM.L, C)  | H, 1 => Some (0, TM.R, G)
  | I, 0 => Some (0, TM.L, J)  | I, 1 => Some (0, TM.L, I)
  | J, 0 => Some (1, TM.R, K)  | J, 1 => Some (0, TM.L, C)
  | K, 0 => Some (0, TM.R, L)  | K, 1 => None
  | L, 0 => Some (0, TM.R, F)  | L, 1 => None
  end.

Notation "c --> c'" := (c -[ tm ]-> c')   (at level 40).
Notation "c -->* c'" := (c -[ tm ]->* c') (at level 40).
Notation "c -->+ c'" := (c -[ tm ]->+ c') (at level 40).

(** ** Tape normalization (as in the hand-written proofs, e.g. BB8_048631_1RB0RG.v) *)

Lemma align_lpow : forall (x : Sym) xs ys n,
  (x::xs)^^n *> x >> ys = x >> (xs ++ [x])^^n *> ys.
Proof.
  induction n.
  - reflexivity.
  - simpl. repeat rewrite Str_app_assoc. rewrite IHn. reflexivity.
Qed.

Lemma align_lpow_const : forall (x : Sym) xs n,
  (x::xs)^^n *> const x = x >> (xs ++ [x])^^n *> const x.
Proof. intros. rewrite const_unfold at 1. apply align_lpow. Qed.

Ltac align_tape := repeat ((rewrite align_lpow || rewrite align_lpow_const); simpl app).
Ltac norm_nat := repeat progress (rewrite ?Nat.add_succ_r, ?Nat.add_0_r; simpl).
(** Adjacent powers of the same block, in either order (crossing a run pushes its powers in reverse order). *)
Lemma lpow_merge : forall (xs : list Sym) n m Y, xs^^n *> xs^^m *> Y = xs^^(n + m) *> Y.
Proof. intros. rewrite lpow_add, Str_app_assoc. reflexivity. Qed.

(** Blank cells in front of the blank tail. *)
Lemma zero_const : (0 >> const 0 : side) = const 0.
Proof. symmetry. apply const_unfold. Qed.

Ltac finish_norm := apply evstep_refl'; norm_nat; align_tape; repeat rewrite lpow_merge; repeat rewrite zero_const;
  try reflexivity; lia_refl.

Lemma lpow_snoc : forall (xs : list Sym) n Y, xs^^(S n) *> Y = xs^^n *> xs *> Y.
Proof. intros. simpl. rewrite <- lpow_shift. apply Str_app_assoc. Qed.


